pub fn solve(s: Vec<char>) -> Vec<char> {
    let mut buffer = Vec::new();
    for c in s {
        match c {
            '0' | '1' => buffer.push(c),
            'B'       => { buffer.pop(); },
            _         => { /* ignore any other input, though by problem statement none should occur */ }
        }
    }
    buffer
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_only_digits() {
        let input: Vec<char> = "0101".chars().collect();
        assert_eq!(solve(input), "0101".chars().collect::<Vec<_>>());
    }

    #[test]
    fn test_backspaces() {
        let input: Vec<char> = "01B1B0".chars().collect();
        // Steps:
        // "0" -> ["0"]
        // "1" -> ["0","1"]
        // "B" -> pop -> ["0"]
        // "1" -> ["0","1"]
        // "B" -> pop -> ["0"]
        // "0" -> ["0","0"]
        assert_eq!(solve(input), "00".chars().collect::<Vec<_>>());
    }

    #[test]
    fn test_leading_backspaces() {
        let input: Vec<char> = "BB01".chars().collect();
        // Leading backspaces do nothing, then "0","1" get appended.
        assert_eq!(solve(input), "01".chars().collect::<Vec<_>>());
    }

    #[test]
    fn test_all_backspaces() {
        let input: Vec<char> = "B".chars().collect();
        assert!(solve(input).is_empty());
    }
}